contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public payable test function
    function run(uint sendAmount, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // observe before-values via public getters
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Make a single top-level state-changing call that may invoke C.receive() if empty calldata and value>0
        // Use C.sendMoney as a top-level call to satisfy the shape requirements; this is a state-changing call on c.
        // We forward sendAmount and arbitrary data to a chosen target: here we call C itself (address(c)).
        // Note: sendMoney is onlyOwner, and this contract is the owner (it deployed C), so the call will be attempted.
        bool didRevert;
        c.sendMoney(address(c), sendAmount, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // observe after-values
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General invariant to assert:
        // - depositsCount never decreases
        // - depositsCount increases by at most 1
        // - if the call reverted, both depositsCount and balance remain unchanged
        bool neverDecreased = afterDeposits >= beforeDeposits;
        bool increasedAtMostOne = (afterDeposits == beforeDeposits) || (afterDeposits == beforeDeposits + 1);
        bool revertedImpliesUnchanged = didRevert ? (afterDeposits == beforeDeposits && afterBal == beforeBal) : true;

        assert(neverDecreased && increasedAtMostOne && revertedImpliesUnchanged);
    }

    // accept Ether when C.transfer/withdraw sends Ether back
    receive() external payable {}
}

