// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 sendAmount, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        bool didRevert;
        try c.sendMoney(address(c), sendAmount, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBal = address(c).balance;
        bool neverDecreased = afterDeposits >= beforeDeposits;
        bool increasedAtMostOne = (afterDeposits == beforeDeposits) || (afterDeposits == beforeDeposits + 1);
        bool revertedImpliesUnchanged = didRevert ? (afterDeposits == beforeDeposits && afterBal == beforeBal) : true;
        assertTrue(neverDecreased && increasedAtMostOne && revertedImpliesUnchanged);
    }

    function testFuzz_run(uint256 sendAmount, bytes memory data) public {
        _run(sendAmount, data);
    }

    receive() external payable {}
}
